#!/usr/bin/env python3
"""Extracts shellUtf8Prefix and SHELL_COMMAND_OUTPUT_MAX_BYTES verbatim from ShellClient.kt.

ShellClient.kt as a whole cannot compile on a host (it pulls in ShellCrypto, ConchNetwork,
ConchHandshake and DebugLog — transport and Android-only logging). ConchSseParser.kt needs only
two declarations from it, so they are lifted out byte for byte rather than retyped.

Usage: python3 extract_shell_prefix.py <ShellClient.kt> <out.kt>
"""
import re
import sys

CONST = "SHELL_COMMAND_OUTPUT_MAX_BYTES"
FUN = "internal fun String.shellUtf8Prefix("

HEADER = """\
// GENERATED by extract_shell_prefix.py from util/ShellClient.kt -- do not edit.
//
// Copied verbatim; only the surrounding file (which cannot compile host-side) is dropped.
package com.newoether.agora.util

"""


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: extract_shell_prefix.py <ShellClient.kt> <out.kt>", file=sys.stderr)
        return 2

    source = open(sys.argv[1], encoding="utf-8").read().split("\n")

    const_index = next((i for i, line in enumerate(source) if f"const val {CONST} " in line), None)
    if const_index is None:
        print(f"error: {CONST} not found", file=sys.stderr)
        return 1

    fun_index = next((i for i, line in enumerate(source) if line.startswith(FUN)), None)
    if fun_index is None:
        print(f"error: {FUN} not found", file=sys.stderr)
        return 1

    # The function body ends at the first line that closes the declaration at column 0.
    fun_end = next((i for i in range(fun_index + 1, len(source)) if source[i] == "}"), None)
    if fun_end is None:
        print("error: end of shellUtf8Prefix not found", file=sys.stderr)
        return 1

    const_line = source[const_index]
    fun_lines = source[fun_index:fun_end + 1]

    block = "\n".join(fun_lines)
    for required in ("maxBytes <= 0", "Character.codePointAt", "0x7ff", "0xffff", "charCount"):
        if required not in block:
            print(f"error: extracted function lost {required!r}", file=sys.stderr)
            return 1

    with open(sys.argv[2], "w", encoding="utf-8") as handle:
        handle.write(HEADER + const_line + "\n\n" + block + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
